<script setup lang="ts">
import PilotageLayout from '../../layouts/PilotageLayout.vue';
import AdminLayout from '../../layouts/AdminLayout.vue';
import { actionLabels, displayDate } from '../../labels';
import { useForm, Link, usePage } from '@inertiajs/vue3'; import BaseLayout from '../../layouts/BaseLayout.vue'; import BaseCard from '../../components/BaseCard.vue'; import FormButton from '../../components/FormButton.vue';
const page = usePage<{ auth: { permissions: string[]; isAdmin?: boolean } }>();
const isPilotage = !page.props.auth.isAdmin && page.props.auth.permissions.includes('pilotage.consulter');
const period = useForm({ debut: '', fin: '' });
const props = defineProps<{ entries: { data: { id: number; actor_id: string | null; action: string; occurred_at: string; details: string }[]; prev_page_url: string | null; next_page_url: string | null }; actors: { id: string; name: string }[]; actions: string[]; filters: { actor?: string; action?: string; date?: string }; pilotageContext?: { event: { id: string; name: string } | null } | null }>(); const form = useForm({ actor: props.filters.actor || '', action: props.filters.action || '', date: props.filters.date || '', event: props.pilotageContext?.event?.id });
</script>
<template><component :is="page.props.auth.isAdmin ? AdminLayout : isPilotage ? PilotageLayout : BaseLayout" active="journal"><Link v-if="!page.props.auth.isAdmin && !isPilotage" href="/espace" class="block min-h-14 underline">Mon espace</Link><h1 class="mb-6 text-display font-bold">Administration · Journal</h1><p class="mb-6">Historique en lecture seule. Aucun événement ne peut être modifié depuis cette interface.</p><BaseCard><form class="space-y-5" @submit.prevent="form.get('/administration/journal')"><label>Acteur<select v-model="form.actor" class="field"><option value="">Tous les acteurs</option><option v-for="actor in actors" :key="actor.id" :value="actor.id">{{ actor.name }}</option></select></label><label>Action<select v-model="form.action" class="field"><option value="">Toutes les actions</option><option v-for="action in actions" :key="action" :value="action">{{ actionLabels[action] || action }}</option></select></label><label>Date<input v-model="form.date" type="date" class="field"></label><FormButton>Filtrer le journal</FormButton></form></BaseCard><BaseCard v-if="page.props.auth.permissions.includes('journal.exporter')" class="mt-6"><h2 class="text-heading font-bold">Exporter le journal</h2><p>Choisissez une période. Le fichier contient uniquement les identifiants et les empreintes, sans nom ni détail libre.</p><form action="/administration/journal/exporter" method="get" class="space-y-4"><label>Du<input v-model="period.debut" name="debut" type="date" class="field" required></label><label>Au<input v-model="period.fin" name="fin" type="date" class="field" required></label><FormButton>Télécharger le CSV</FormButton></form></BaseCard><ol class="my-6 space-y-4"><li v-for="entry in entries.data" :key="entry.id"><BaseCard><p class="font-semibold">{{ actionLabels[entry.action] || entry.action }}</p><p>{{ displayDate(entry.occurred_at) }}</p><p>{{ actors.find(a => a.id === entry.actor_id)?.name || 'Système / non identifié' }}</p><details class="mt-3"><summary class="min-h-14 cursor-pointer py-3">Détails</summary><pre class="whitespace-pre-wrap break-all">{{ entry.details }}</pre></details></BaseCard></li></ol><p v-if="!entries.data.length">Aucun événement pour ces filtres.</p><nav class="flex gap-4"><Link v-if="entries.prev_page_url" :href="entries.prev_page_url" class="action">Précédent</Link><Link v-if="entries.next_page_url" :href="entries.next_page_url" class="action">Suivant</Link></nav></component></template>
